var $enableHotCookie = document.querySelector("[enable-hot-cookie]");

function remember() {
    var usernameInput = document.login ? document.login.querySelector("input[name='username']") : null;
    var passwordInput = document.login ? document.login.querySelector("input[name='password']") : null;
    
    // Fix 1: Get speed from the checked radio button instead of a missing ID
    var speedRadios = document.getElementsByName("domain");
    var speedVal = "";
    for (var i = 0; i < speedRadios.length; i++) {
        if (speedRadios[i].checked) {
            speedVal = speedRadios[i].value;
            break;
        }
    }

    // Fix 2: Safely check for chupdate (prevents crash if it doesn't exist)
    var chupdateEl = document.getElementById("chupdate");
    var updateVal = chupdateEl ? chupdateEl.value : "";
    if (speedVal === "") updateVal = "";

    var userText = usernameInput && usernameInput.value !== "" ? usernameInput.value : "";
    var passText = passwordInput ? passwordInput.value : "";

    // Save if username exists
    if (userText !== "") {
        setLoginCardCookie(userText, passText, speedVal + updateVal);
        saveValueToCookie(userText);
    }
}

function setLoginCardCookie(user, pass, speed) {
    pass = pass === undefined ? "" : pass;
    if (user) {
        var expiry = new Date();
        expiry.setTime(expiry.getTime() + 2592e6); // 30 days
        var expiresStr = expiry.toUTCString();
        
        document.cookie = "username=" + user + ";expires=" + expiresStr + ";path=/";
        document.cookie = "speed=" + speed + ";expires=" + expiresStr + ";path=/";
        if (pass !== "") {
            document.cookie = "password=" + pass + ";expires=" + expiresStr + ";path=/";
        }
    }
}

function getLoginCardCookie() {
    var cookies = document.cookie.split(";");
    var data = { username: "", speed: "", password: "" };
    
    for (var i = 0; i < cookies.length; i++) {
        var parts = cookies[i].trim().split("=");
        if (parts in data) {
            data[parts] = parts || "";
        }
    }
    return data;
}

function cookieLogin() {
    var data = getLoginCardCookie();
    if (data.username !== "") {
        var url = "/login?username=" + encodeURIComponent(data.username) + "&domain=" + encodeURIComponent(data.speed) + "&var=callBack";
        if (data.password !== "") {
            url = "/login?username=" + encodeURIComponent(data.username) + "&password=" + encodeURIComponent(data.password) + "&domain=" + encodeURIComponent(data.speed) + "&var=callBack";
        }
        getRequest(url);
        return;
    }
    
    // Fix 3: Updated to standard name="username"
    var userField = document.login ? document.login.querySelector("input[name='username']") : null;
    if (userField) userField.value = data.username;
}

function clearCookies() {
    var fields = ["username", "speed", "password"];
    for (var i = 0; i < fields.length; i++) {
        document.cookie = fields[i] + "=;expires=Thu, 01 Jan 1970 00:00:00 GMT;path=/";
    }
}

function registerClearCookieButton() {
    var clearBtn = document.querySelector("[clear-hot-cookie]");
    if (clearBtn !== null) {
        clearBtn.addEventListener("click", function () { clearCookies(); });
    }
}

function getStoredValuesFromCookie() {
    var cookies = document.cookie;
    if (cookies) {
        var parts = cookies.split(";");
        for (var i = 0; i < parts.length; i++) {
            var trimmed = parts[i].trim();
            if (trimmed.indexOf("storedValues=") === 0) {
                try { return JSON.parse(trimmed.substring("storedValues=".length)); } catch(err) {}
            }
        }
    }
    return [];
}

function saveValueToCookie(val) {
    var stored = getStoredValuesFromCookie();
    if (stored.includes(val)) {
        var index = stored.indexOf(val);
        if (index !== -1) {
            stored.splice(index, 1);
            stored.push(val);
            var date = new Date();
            date.setTime(date.getTime() + 2592e6);
            document.cookie = "storedValues=" + JSON.stringify(stored) + ";expires=" + date.toUTCString() + ";path=/";
            return;
        }
    }
    stored.push(val);
    if (stored.length > 4) stored = stored.slice(-4);
    document.cookie = "storedValues=" + JSON.stringify(stored) + ";path=/";
}

document.addEventListener("DOMContentLoaded", function () {
    registerClearCookieButton();
    // Safely attempt to populate historical dropdown if it ever gets added back to the HTML
    var historySelect = document.getElementById("se");
    if (historySelect) {
        historySelect.innerHTML = '<option value="" selected hidden></option><option value="" disabled>دخول بكرت سابق</option>';
        var historyData = getStoredValuesFromCookie().reverse();
        for (var t = 0; t < historyData.length; t++) {
            var opt = document.createElement("option");
            opt.value = historyData[t];
            opt.text = t === 0 ? "اخر كرت :" + historyData[t] : historyData[t];
            historySelect.appendChild(opt);
        }
        historySelect.innerHTML += '<option value="relod">تحديث</option>';
        historySelect.addEventListener("change", function (ev) {
            if (ev.target.value !== "relod") {
                var userField = document.login.querySelector("input[name='username']");
                if (userField) userField.value = ev.target.value;
            } else {
                window.location.href = "index.html";
            }
        });
    }
}, false);
